1	// Test harness: spawn server.mjs, raw HTTP requests, temp dirs.
2	import { spawn } from 'node:child_process';
3	import fs from 'node:fs';
4	import http from 'node:http';
5	import os from 'node:os';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
10	export const SERVER = path.join(ROOT, 'server.mjs');
11	const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
12	const TIMEOUT_MS = 8000;
13	
14	export function tmpDir(t) {
15	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rooms-test-'));
16	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
17	  return dir;
18	}
19	
20	function buildEnv(overrides, dataFile) {
21	  const env = { ...process.env, PORT: '0', DATA_FILE: dataFile, ...overrides };
22	  for (const [key, value] of Object.entries(env)) {
23	    if (value === undefined) delete env[key];
24	  }
25	  return env;
26	}
27	
28	function launch(t, { env = {}, cwd, dataFile }) {
29	  const child = spawn(process.execPath, [SERVER], {
30	    env: buildEnv(env, dataFile),
31	    cwd,
32	    stdio: ['ignore', 'pipe', 'pipe'],
33	  });
34	  const out = { stdout: '', stderr: '' };
35	  child.stdout.setEncoding('utf8');
36	  child.stderr.setEncoding('utf8');
37	  child.stdout.on('data', (d) => { out.stdout += d; });
38	  child.stderr.on('data', (d) => { out.stderr += d; });
39	  const closed = new Promise((resolve) => {
40	    child.once('close', (code, signal) => resolve({ code, signal }));
41	  });
42	  t.after(() => { child.kill('SIGKILL'); });
43	  return { child, out, closed };
44	}
45	
46	function waitForListening({ child, out, closed }) {
47	  return new Promise((resolve, reject) => {
48	    const timer = setTimeout(() => reject(new Error('server did not start in time')), TIMEOUT_MS);
49	    child.stdout.on('data', () => {
50	      const match = LISTEN_RE.exec(out.stdout);
51	      if (match) {
52	        clearTimeout(timer);
53	        resolve(Number(match[1]));
54	      }
55	    });
56	    closed.then((r) => {
57	      clearTimeout(timer);
58	      reject(new Error(`server exited early (code ${r.code}): ${out.stderr}`));
59	    });
60	  });
61	}
62	
63	export async function startServer(t, opts = {}) {
64	  const dir = opts.dir ?? tmpDir(t);
65	  const dataFile = opts.dataFile ?? path.join(dir, 'data.json');
66	  const proc = launch(t, { env: opts.env, cwd: opts.cwd ?? dir, dataFile });
67	  const port = await waitForListening(proc);
68	  return {
69	    port,
70	    dir,
71	    dataFile,
72	    child: proc.child,
73	    stdout: () => proc.out.stdout,
74	    stderr: () => proc.out.stderr,
75	    async stop() {
76	      proc.child.kill('SIGTERM');
77	      await proc.closed;
78	      return proc.out.stdout;
79	    },
80	    req: (o) => request(port, o),
81	  };
82	}
83	
84	export async function runToExit(t, opts = {}) {
85	  const dir = opts.dir ?? tmpDir(t);
86	  const dataFile = opts.dataFile ?? path.join(dir, 'data.json');
87	  const proc = launch(t, { env: opts.env, cwd: opts.cwd ?? dir, dataFile });
88	  let timer;
89	  const timeout = new Promise((_, reject) => {
90	    timer = setTimeout(() => reject(new Error('server did not exit in time')), TIMEOUT_MS);
91	  });
92	  try {
93	    const { code } = await Promise.race([proc.closed, timeout]);
94	    return { code, stdout: proc.out.stdout, stderr: proc.out.stderr };
95	  } finally {
96	    clearTimeout(timer);
97	  }
98	}
99	
100	function toReply(res, raw) {
101	  const body = raw.toString('utf8');
102	  let json;
103	  try { json = JSON.parse(body); } catch { json = undefined; }
104	  return { status: res.statusCode, headers: res.headers, raw, body, json };
105	}
106	
107	// Raw request: `path` is sent exactly as given (http.request does not normalise it).
108	export function request(port, { method = 'GET', path: target = '/', headers = {}, body, chunks } = {}) {
109	  return new Promise((resolve, reject) => {
110	    const sent = chunks ? { ...headers, 'Transfer-Encoding': 'chunked' } : headers;
111	    const req = http.request(
112	      { host: '127.0.0.1', port, method, path: target, headers: sent, agent: false },
113	      (res) => {
114	        const parts = [];
115	        res.on('data', (c) => parts.push(c));
116	        res.on('end', () => resolve(toReply(res, Buffer.concat(parts))));
117	        res.on('error', reject);
118	      },
119	    );
120	    req.setTimeout(TIMEOUT_MS, () => req.destroy(new Error('request timed out')));
121	    req.on('error', reject);
122	    if (chunks) {
123	      for (const chunk of chunks) req.write(chunk);
124	      req.end();
125	    } else {
126	      req.end(body);
127	    }
128	  });
129	}
